(function () {

    if (window.createNotification) return;

    const notif = document.createElement('div');

    notif.style.cssText = `
        position: fixed;
        bottom: 40px;
        right: 55px;
        background: #8f91dba3;
        color: white;
        font-style: normal;
        font-family: "GothamPro Black", system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif;
        font-weight: 700;
        padding: 8px 12px;
        border-radius: 6px;
        font-size: 12px;
        z-index: 9999;
        opacity: 0;
        transform: translateX(20px);
        transition: opacity 0.12s ease, transform 0.12s ease;
        pointer-events: none;
    `;

    document.body.appendChild(notif);

    let timeout;

    function createNotification(title, text) {

        notif.innerHTML = `<b>${title}</b><br>${text}`;

        notif.style.opacity = "1";
        notif.style.transform = "translateX(0)";

        clearTimeout(timeout);

        timeout = setTimeout(() => {
            notif.style.opacity = "0";
            notif.style.transform = "translateX(20px)";
        }, 2000);
    }

    window.createNotification = createNotification;

})();

let logoStyle = null;
let logoWidth = 18.54; 
let logoHeight = 5.2; 

function applyLogoSize(w = logoWidth, h = logoHeight) {

    logoWidth = w;
    logoHeight = h;

    if (logoStyle) {
        logoStyle.remove();
        logoStyle = null;
    }

    const style = document.createElement("style");

    style.innerHTML = `
        .Old-Fixed-Logo img {
            width: ${logoWidth}vh !important;
            height: ${logoHeight}vh !important;
        }
    `;

    document.head.appendChild(style);

    logoStyle = style;
}

function openLogoMenu() {

    window.addDialogInQueue(
        `[0,1,"LOGO","Введите размер (ширина высота, например: 20 6)","Применить","Закрыть",0,0]`,
        "",
        0
    );

    const orig = window.sendClientEvent;

    window.sendClientEvent = function (...args) {

        if (args.includes("OnDialogResponse")) {

            let input = (args[5] || "").trim();

            const parts = input.split(" ");

            let w = parseFloat(parts[0]);
            let h = parseFloat(parts[1]);

            if (!isNaN(w) && !isNaN(h)) {
                applyLogoSize(w, h);
            }

            window.sendClientEvent = orig;
        }

        return orig.apply(this, args);
        
    };
}

(function () {

    const wait = setInterval(() => {

        if (!window.sendChatInput) return;

        clearInterval(wait);

        const orig = window.sendChatInput;

        window.sendChatInput = function (...a) {

            const msg = a.join("").trim();

            if (msg === "/logo") {
                openLogoMenu();
                return;
            }

            return orig.apply(this, a);
        };

    }, 500);

})();

const observer = new MutationObserver(() => {
    applyLogoSize();
});

function startObserver() {
    const target = document.querySelector("#app");
    if (!target) return;

    observer.observe(target, {
        childList: true,
        subtree: true
    });
}

setTimeout(startObserver, 2000);

applyLogoSize();

let currentRadarStyle = null;
let currentType = "oval";
let radarColor = "#F000";

function getBorder() {
    return radarColor
        ? `0.60vh solid ${radarColor}`
        : `0vh solid transparent`;
}

function getRadarCSS(type) {

    if (type === "square") return `
        #app .hud-radmir-radar__map {
            width: 21.9vh !important;
            height: 20.9vh !important;
            border-radius: 2vh;
            border: ${getBorder()} !important;
        }
    `;

    if (type === "rect") return `
        #app .hud-radmir-radar__map {
            width: 26.3vh !important;
            height: 16.9vh !important;
            border-radius: 2vh;
            border: ${getBorder()} !important;
        }
    `;

    if (type === "oval") return `
        #app .hud-radmir-radar__map {
            width: 24vh !important;
            height: 18.6vh !important;
            border-radius: 100%;
            border: ${getBorder()} !important;
        }
    `;

    if (type === "round") return `
        #app .hud-radmir-radar__map {
            width: 22vh !important;
            height: 22vh !important;
            border-radius: 100%;
            border: ${getBorder()} !important;
        }
    `;
}

function applyRadar(type = currentType) {

    currentType = type;

    if (currentRadarStyle) {
        currentRadarStyle.remove();
    }

    const style = document.createElement("style");
    style.innerHTML = getRadarCSS(type);

    document.head.appendChild(style);
    currentRadarStyle = style;
}

function setRadar(type, name) {
    applyRadar(type);

    createNotification(
        "Смена радара",
        `Выбран: ${name}`
    );
}

function openRadarMenu() {

    const list = "Квадратный<n>Круглый<n>Прямоугольный<n>Овальный<n>Цвет";

    window.addDialogInQueue(
        `[0,2,"Смена радара LOGRAGE","Выберите тип радара:","Выбрать","Закрыть",0,0]`,
        list,
        0
    );

    const orig = window.sendClientEvent;

    window.sendClientEvent = function (...args) {

        if (args.includes("OnDialogResponse")) {

            const raw = (args[5] || "").toLowerCase();

            if (raw.includes("квад")) setRadar("square", "Квадратный");
            if (raw.includes("круг")) setRadar("round", "Круглый");
            if (raw.includes("прям")) setRadar("rect", "Прямоугольный");
            if (raw.includes("овал")) setRadar("oval", "Овальный");

            if (raw.includes("цвет")) {
                setTimeout(openColorMenu, 100);
            }

            window.sendClientEvent = orig;
        }

        return orig.apply(this, args);
    };
}

function openColorMenu() {

    window.addDialogInQueue(
        `[0,1,"Цвет Обводки радара","Введите (#FF0000 или убрать #F000)","Ок","Назад",0,0]`,
        "",
        0
    );

    const orig = window.sendClientEvent;

    window.sendClientEvent = function (...args) {

        if (args.includes("OnDialogResponse")) {

            let input = (args[5] || "").trim().toLowerCase();
            input = input.replace("#", "");

            if (/^[0-9a-f]{3}$/.test(input)) {
                radarColor = "#" + input.split("").map(c => c + c).join("");
            }
            else if (/^[0-9a-f]{6}$/.test(input)) {
                radarColor = "#" + input;
            }
            else {
                radarColor = null;
            }

            applyRadar();

            createNotification(
                "Вы выбрали данный",
                radarColor ? `Цвет: ${radarColor}` : "Цвет отключен"
            );

            window.sendClientEvent = orig;
        }

        return orig.apply(this, args);
    };
}

(function () {

    const wait = setInterval(() => {

        if (!window.sendChatInput) return;

        clearInterval(wait);

        const orig = window.sendChatInput;

        window.sendChatInput = function (...a) {

            const msg = a.join("").trim();

            if (msg === "/radar") {
                openRadarMenu();
                return;
            }

            return orig.apply(this, a);
        };

    }, 500);

})();

applyRadar();

let interfaceStyle = null;

function hexToRgb(hex) {
    hex = hex.replace(/^#/, "");

    if (hex.length === 3) {
        hex = hex.split("").map(c => c + c).join("");
    }

    if (hex.length !== 6) return null;

    return {
        r: parseInt(hex.substring(0, 2), 16),
        g: parseInt(hex.substring(2, 4), 16),
        b: parseInt(hex.substring(4, 6), 16),
    };
}

function getLuminance(r, g, b) {
    const [r0, g0, b0] = [r, g, b].map(c => {
        c = c / 255;
        return c <= 0.03928
            ? c / 12.92
            : Math.pow((c + 0.055) / 1.055, 2.4);
    });

    return 0.2126 * r0 + 0.7152 * g0 + 0.0722 * b0;
}

function applyInterfaceColor(inputColor) {

    let color = inputColor.trim();
    if (!color) return;

    if (color[0] !== "#") color = "#" + color;

    if (!/^#([0-9a-f]{3}|[0-9a-f]{6})$/i.test(color)) {
        createNotification("Ошибка", "Неверный # цвет");
        return;
    }

    if (color.length === 4) {
        color = "#" + color[1]+color[1]+color[2]+color[2]+color[3]+color[3];
    }

    const rgb = hexToRgb(color);
    if (!rgb) return;

    const luminance = getLuminance(rgb.r, rgb.g, rgb.b);

    const textColor = luminance > 0.5 ? "#000000" : "#FFFFFF";
    const borderColor = luminance > 0.5 ? "#00000033" : "#FFFFFF33";
    const hoverColor = luminance > 0.5 ? "#0000001a" : "#FFFFFF1a";
    const activeColor = luminance > 0.5 ? "#0000004d" : "#FFFFFF4d";

const alpha = "80";

const css = `
    #app .modal-container,
    #app .modal-container-wrapper {
        background: ${color} !important;
    }

    #app .player-interaction__inner {
         background: ${color} !important;
         border: .09vh solid ${borderColor} !important;
    }

    #app .player-interaction-layer {
         background: ${color}${alpha} !important;

    }

    #app .player-interaction__container {
         background: ${color}${alpha} !important;
    }

    #app .player-interaction-favorite {
         background: ${color}${alpha} !important;
    }

    #app .player-interaction-favorite:hover {
         background: ${color}${alpha} !important;
    }

    #app .container {
         background: ${color}${alpha} !important;
    }

    #app .input-field {
        background: ${color}${alpha} !important;
        color: ${textColor} !important;
        border: 1px solid ${borderColor} !important;
    }

    #app .fuel__container {
        background: ${color}${alpha} !important;
    }

    #app .controls-button {
        background: ${color}${alpha} !important;
    }

    #app .radmir-chat-input__input {
        background: ${color}${alpha} !important;
        border: 1px solid ${borderColor} !important;
    }

    #app .inventory-action__modal {
        background: ${color}${alpha} !important;

    }
         .inventory-container__info__container {
        background: ${color}${alpha} !important;

}
    #app .inventory-extra__container,
    #app .inventory-main {
        background: ${color}${alpha} !important;

}
    #app .trade-items__container {
        background: ${color}${alpha} !important;
}
`;

    if (interfaceStyle) interfaceStyle.remove();

    const style = document.createElement("style");
    style.innerHTML = css;
    document.head.appendChild(style);

    interfaceStyle = style;

    createNotification("Интерфейс", `Цвет: ${color}`);
}


function openInterfaceMenu() {

    window.addDialogInQueue(
        `[0,1,"Цвет интерфейса","Введите Цвет (#FF0000)","Применить","Закрыть",0,0]`,
        "",
        0
    );

    const orig = window.sendClientEvent;

    window.sendClientEvent = function (...args) {

        if (args.includes("OnDialogResponse")) {

            const input = (args[5] || "").trim();

            applyInterfaceColor(input);

            window.sendClientEvent = orig;
        }

        return orig.apply(this, args);
    };
}

