function showGameText(text = "MERKURY MODS HUD", duration = 4000) {
    try {
        if (typeof window.openInterface === "function") {
            window.openInterface('GameText');
        }

        if (window.interface && window.interface("GameText")) {
            const gameText = window.interface("GameText");

            gameText.text = text;

            gameText.show = true;

            setTimeout(() => {
                gameText.show = false;
            }, duration);
        } else {
            console.log("GameText");
        }
    } catch (e) {
        console.error("error showGameText:", e);
    }
}
